import React, { createContext, useCallback, useContext, useRef, useState } from 'react';
import './App.css';

// The preview passes useState, useEffect, useMemo, useRef, useReducer, useContext,
// createContext and useCallback in as globals. Reach any other hook through React,
// for example React.useLayoutEffect.

type CommonSelectProps = {
  label: string;
  placeholder?: string;
  className?: string;
  children: React.ReactNode;
};

type SingleSelectProps = CommonSelectProps & {
  multiple?: false;
  value: string | null;
  onChange: (value: string | null) => void;
};

type MultiSelectProps = CommonSelectProps & {
  multiple: true;
  value: string[];
  onChange: (value: string[]) => void;
};

export type SelectProps = SingleSelectProps | MultiSelectProps;

type SelectOptionProps = {
  value: string;
  label: string;
  disabled?: boolean;
  children?: React.ReactNode;
};

type SelectContextValue = {
  open: boolean;
  multiple: boolean;
  placeholder: string;
  selected: string[];
  labels: Map<string, string>;
  labelId: string;
  valueId: string;
  listboxId: string;
  toggleOpen: () => void;
  choose: (value: string) => void;
  registerOption: (value: string, label: string) => () => void;
};

const SelectContext = createContext<SelectContextValue | null>(null);

function useSelectContext(part: string): SelectContextValue {
  const context = useContext(SelectContext);
  if (!context) {
    throw new Error(`<Select.${part}> must be rendered inside <Select>`);
  }
  return context;
}

let nextSelectId = 0;

function SelectRoot(props: SelectProps) {
  const { label, placeholder = 'Select…', className, children } = props;
  const [open, setOpen] = useState(false);
  const [labels, setLabels] = useState<Map<string, string>>(() => new Map());
  const idRef = useRef('');
  if (!idRef.current) {
    nextSelectId += 1;
    idRef.current = `select-${nextSelectId}`;
  }

  const selected = props.multiple ? props.value : props.value === null ? [] : [props.value];

  function choose(value: string) {
    if (props.multiple) {
      const next = props.value.includes(value)
        ? props.value.filter((item) => item !== value)
        : [...props.value, value];
      props.onChange(next);
      return;
    }
    props.onChange(value);
    setOpen(false);
  }

  const registerOption = useCallback((value: string, optionLabel: string) => {
    setLabels((current) => {
      if (current.get(value) === optionLabel) return current;
      const next = new Map(current);
      next.set(value, optionLabel);
      return next;
    });
    return () => {
      setLabels((current) => {
        if (!current.has(value)) return current;
        const next = new Map(current);
        next.delete(value);
        return next;
      });
    };
  }, []);

  const context: SelectContextValue = {
    open,
    multiple: Boolean(props.multiple),
    placeholder,
    selected,
    labels,
    labelId: `${idRef.current}-label`,
    valueId: `${idRef.current}-value`,
    listboxId: `${idRef.current}-listbox`,
    toggleOpen: () => setOpen((current) => !current),
    choose,
    registerOption
  };

  return (
    <SelectContext.Provider value={context}>
      <div
        className={['select', className].filter(Boolean).join(' ')}
        onKeyDown={(event: React.KeyboardEvent<HTMLDivElement>) => {
          if (event.key === 'Escape') setOpen(false);
        }}
      >
        <span className="select__label" id={context.labelId}>{label}</span>
        {children}
      </div>
    </SelectContext.Provider>
  );
}

function SelectTrigger() {
  const { open, selected, labels, placeholder, labelId, valueId, listboxId, toggleOpen } = useSelectContext('Trigger');
  const text = selected.length ? selected.map((value) => labels.get(value) ?? value).join(', ') : placeholder;
  return (
    <button
      type="button"
      className="select__trigger"
      aria-haspopup="listbox"
      aria-expanded={open}
      aria-controls={listboxId}
      aria-labelledby={`${labelId} ${valueId}`}
      onClick={toggleOpen}
    >
      <span className="select__value" id={valueId}>{text}</span>
    </button>
  );
}

function SelectOptions({ children }: { children: React.ReactNode }) {
  const { open, multiple, labelId, listboxId } = useSelectContext('Options');
  return (
    <ul
      id={listboxId}
      className="select__options"
      role="listbox"
      aria-labelledby={labelId}
      aria-multiselectable={multiple || undefined}
      hidden={!open}
    >
      {children}
    </ul>
  );
}

function SelectOption({ value, label, disabled = false, children }: SelectOptionProps) {
  const { selected, choose, registerOption } = useSelectContext('Option');
  React.useLayoutEffect(() => registerOption(value, label), [registerOption, value, label]);
  const isSelected = selected.includes(value);
  return (
    <li
      className="select__option"
      role="option"
      aria-selected={isSelected}
      aria-disabled={disabled || undefined}
      onClick={() => {
        if (!disabled) choose(value);
      }}
    >
      {children ?? label}
    </li>
  );
}

export const Select = Object.assign(SelectRoot, {
  Trigger: SelectTrigger,
  Options: SelectOptions,
  Option: SelectOption
});

const TOPPINGS = [
  { value: 'nuts', label: 'Nuts', icon: 'N' },
  { value: 'honey', label: 'Honey', icon: 'H' },
  { value: 'granola', label: 'Granola', icon: 'G' },
  { value: 'yogurt', label: 'Yogurt', icon: 'Y' }
];

export default function App() {
  const [fruit, setFruit] = useState<string | null>(null);
  const [toppings, setToppings] = useState<string[]>(['nuts']);

  return (
    <main className="main">
      <section className="card">
        <header className="header">
          <h1 className="title">Select</h1>
          <p className="subtitle">One compound API for single and multi-select, with custom option content.</p>
        </header>

        <Select className="fruit-select" label="Fruit" placeholder="Choose a fruit" value={fruit} onChange={setFruit}>
          <Select.Trigger />
          <Select.Options>
            <Select.Option value="apple" label="Apple" />
            <Select.Option value="banana" label="Banana">
              <span className="option-title">Banana</span>
              <span className="option-note">Ripe today</span>
            </Select.Option>
            <Select.Option value="cherry" label="Cherry" disabled />
            <Select.Option value="dragon" label="Dragon fruit" />
          </Select.Options>
        </Select>
        <p className="single-value">Fruit: {fruit ?? 'none'}</p>

        <Select className="toppings-select" label="Toppings" placeholder="Add toppings" multiple value={toppings} onChange={setToppings}>
          <Select.Trigger />
          <Select.Options>
            {TOPPINGS.map((topping) => (
              <Select.Option key={topping.value} value={topping.value} label={topping.label}>
                <span className="option-icon" aria-hidden="true">{topping.icon}</span>
                <span className="option-title">{topping.label}</span>
              </Select.Option>
            ))}
          </Select.Options>
        </Select>
        <p className="multi-value">Toppings: {toppings.length ? toppings.join(', ') : 'none'}</p>
      </section>
    </main>
  );
}
